add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_force_cart_total_deposit', 999 );

function perfectpixel_force_cart_total_deposit( $cart ) {
	if ( is_admin() && ! wp_doing_ajax() ) {
		return;
	}
	$deposit = (float) '{{deposit_amount}}';
	// Everything already in the total: items + shipping + other fees (incl. taxes).
	$current = (float) $cart->get_subtotal() + (float) $cart->get_subtotal_tax() + (float) $cart->get_shipping_total() + (float) $cart->get_shipping_tax();
	foreach ( $cart->get_fees() as $fee ) {
		$current += (float) $fee->total + (float) $fee->tax;
	}
	$current -= (float) $cart->get_discount_total() + (float) $cart->get_discount_tax();

	if ( $deposit > 0 && $current > $deposit ) {
		$cart->add_fee( '{{deposit_label}}', -( $current - $deposit ), false );
	}
}
